ga5z(){return"\u0663 \xb7 \u062a\u064f\u0628\u0646\u0649 \u0645\u062e\u0637\u0637\u0627\u062a\u0643 \u0648\u0645\u062a\u0627\u0628\u0639\u062a\u0643 \u0645\u0646 \u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u0645\u0624\u0643\u064e\u0651\u062f\u0629."},
ga5w(){return"\u062a\u064f\u0631\u0633\u0644 \u0635\u0648\u0631\u0629 \u0627\u0644\u0645\u0633\u062a\u0646\u062f \u0625\u0644\u0649 \u062e\u062f\u0645\u0629 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u062e\u0627\u0631\u062c\u064a\u0629 \u0644\u0642\u0631\u0627\u0621\u062a\u0647\u0627. \u0644\u0627 \u064a\u064f\u0631\u0633\u0644 \u0645\u0639\u0647\u0627 \u0627\u0633\u0645\u0643 \u0648\u0644\u0627 \u0631\u0642\u0645\u0643 \u0627\u0644\u0635\u062d\u064a \u0648\u0644\u0627 \u0623\u064a \u0645\u0639\u0644\u0648\u0645\u0629 \u062a\u0639\u0631\u0651\u0641\u0643\u060c \u0648\u0644\u0627 \u0646\u0633\u062c\u0651\u0644 \u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0641\u064a \u0623\u064a \u0633\u062c\u0644 \u062a\u0634\u063a\u064a\u0644\u064a. \u0648\u0644\u0627 \u062a\u064f\u0636\u0627\u0641 \u0623\u064a \u0642\u064a\u0645\u0629 \u0625\u0644\u0649 \u0633\u062c\u0644\u0651\u0643 \u0642\u0628\u0644 \u0623\u0646 \u062a\u0624\u0643\u0651\u062f\u0647\u0627 \u0623\u0646\u062a."},
ga5v(){return"\u0641\u0647\u0645\u062a"},
gaet(){return"\u0642\u0631\u0623\u0646\u0627 \u0647\u0630\u0647 \u0627\u0644\u0643\u0644\u0645\u0629 \u0644\u0643\u0646 \u0644\u0627 \u0646\u0639\u0631\u0641\u0647\u0627 \u2014 \u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a\u061f"},
gaem(){return"\u0625\u064a\u062c\u0627\u0628\u064a"},
gael(){return"\u0633\u0644\u0628\u064a"},
gaeC(){return"\u0623\u0636\u0641 \u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u0629 \u0641\u064a \u0627\u0644\u0648\u0631\u0642\u0629"},
gahW(){return"\u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u062a\u064a \u062a\u0624\u0643\u0651\u062f\u0647\u0627 \u0645\u0646 \u062a\u0642\u0631\u064a\u0631 \u0645\u0631\u0641\u0648\u0639 \u062a\u0638\u0647\u0631 \u0647\u0646\u0627"},
gSE(){return"\u062a\u0639\u0630\u0651\u0631 \u0639\u0631\u0636 \u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
gamO(){return"\u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629"},
acw(a,b){return"\u0635\u0641\u062d\u0629 "+a+" \u0645\u0646 "+b},
gaef(){return"\u0644\u0627 \u064a\u0645\u0643\u0646\u0646\u0627 \u062a\u062d\u062f\u064a\u062f \u0645\u0648\u0636\u0639 \u0647\u0630\u0647 \u0627\u0644\u0642\u064a\u0645\u0629 \u0641\u064a \u0627\u0644\u0635\u0641\u062d\u0629 \u2014 \u062a\u062d\u0642\u0651\u0642 \u0645\u0646\u0647\u0627 \u0628\u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
Td(a){return""+a+" \u062a\u0642\u0631\u064a\u0631 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0645\u0631\u0627\u062c\u0639\u062a\u0643"},
gTc(){return"\u0631\u0627\u062c\u0639\u0647\u0627 \u0627\u0644\u0622\u0646"},
gacx(){return"\u0627\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629"},
