gan4(){return"\u0628\u0695\u06cc\u0627\u0631\u06d5\u06a9\u0627\u0646 \u0628\u0646\u06ce\u0631\u06d5"},
gXa(){return"\u0628\u0695\u06cc\u0627\u0631\u06d5\u06a9\u0627\u0646\u062a"},
